export function normalizeNigerianPhone(input) {
  if (typeof input !== 'string') {
    return null;
  }

  // Remove whitespace, '-', '.', '(', ')'
  const cleanedInput = input.replace(/[\s\-\.\(\)]/g, '');

  // Check for invalid characters
  if (/[^+\d]/.test(cleanedInput) || (cleanedInput.match(/\+/g) || []).length > 1) {
    return null;
  }

  // Remove leading '+'
  let digits = cleanedInput.startsWith('+') ? cleanedInput.slice(1) : cleanedInput;

  // Handle country code
  if (digits.startsWith('234')) {
    digits = digits.slice(3);
  } else if (digits.startsWith('00234')) {
    digits = digits.slice(5);
  } else if (digits.startsWith('0')) {
    digits = digits.slice(1);
  } else {
    return null;
  }

  // Validate national number
  if (!/^[789][01]\d{8}$/.test(digits)) {
    return null;
  }

  return `+234${digits}`;
}

export function formatNigerianPhone(input) {
  const normalized = normalizeNigerianPhone(input);
  if (normalized === null) {
    return null;
  }

  const nationalNumber = normalized.slice(4); // Remove '+234'
  return `0${nationalNumber.slice(0, 3)} ${nationalNumber.slice(3, 6)} ${nationalNumber.slice(6)}`;
}
